+  const metadata = [
+    page.date ? `<time datetime="${escapeHtml(page.date)}">${escapeHtml(page.date)}</time>` : '',
+    page.tags.length > 0
+      ? `<ul class="tags">${page.tags.map((tag) => `<li>${escapeHtml(tag)}</li>`).join('')}</ul>`
+      : ''
+  ].filter(Boolean).join('\n');
